contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address logger, bool status) public payable {
        require(caller != address(this), "caller must not be the test contract");

        c.setApprovedLogger(logger, status);

        bool callerBefore = c.approvedToLog(caller);
        bool loggerBefore = c.approvedToLog(logger);

        bool reverted;
        try c.logCreated(caller) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool callerAfter = c.approvedToLog(caller);
        bool loggerAfter = c.approvedToLog(logger);

        assert(
            callerBefore == callerAfter &&
            loggerBefore == loggerAfter &&
            !reverted &&
            (callerAfter || caller != logger)
        );
    }

    receive() external payable {}
}

