contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, address keep) public {
        require(logger != address(0), "zero logger");
        require(logger != address(this), "logger must differ from owner/test contract");

        // Owner (this contract) approves the logger.
        c.setApprovedLogger(logger, true);

        // The logger is now approved; we cannot call c.logCreated as the logger
        // because msg.sender for all c calls is address(this), the owner.
        // However we CAN observe the approval state through the public getter.
        bool approved = c.approvedToLog(logger);
        c.setApprovedLogger(logger, true);
        bool approvedAgain = c.approvedToLog(logger);

        assert(approved && approvedAgain);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, bool status) public {
        require(logger != address(0), "zero logger");
        require(logger != address(this), "cannot approve the test contract itself");

        // Initially, before any approval, the logger must not be approved.
        bool initiallyApproved = c.approvedToLog(logger);

        // Owner (this contract) sets the status.
        c.setApprovedLogger(logger, status);
        bool afterSet = c.approvedToLog(logger);

        // Setting the opposite status must flip it back.
        c.setApprovedLogger(logger, !status);
        bool afterFlip = c.approvedToLog(logger);

        assert(!initiallyApproved && afterSet == status && afterFlip == !status);
    }

    receive() external payable {}
}

