contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bool newStatus, address keepAddr, bytes32 digest, uint256 utxoSize, bytes memory outputScript, uint256 requestedFee, bytes memory outpoint, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bool wasFraud, bytes32 txid) public {
        // Ensure the caller is NOT approved. Set it explicitly.
        c.setApprovedLogger(caller, false);

        // Record the approval status before the calls.
        bool before = c.approvedToLog(caller);

        bool r1;
        bool r2;
        bool r3;
        bool r4;
        bool r5;
        bool r6;
        bool r7;
        bool r8;
        bool r9;
        bool r10;
        bool r11;
        bool r12;

        if (caller == msg.sender) {
            // msg.sender is the test contract, which is also the owner and could be approved if the user calls setApprovedLogger.
            // But we want to test non-approved behaviour only. To make the test deterministic, we must ensure callers used here are not msg.sender.
            // Since we cannot enforce that through require without possibly skipping the test entirely,
            // we simply avoid using msg.sender as the caller by requiring caller != msg.sender.
            require(caller != msg.sender, "caller must not be the test contract");
        }

        // Call each logging function. Since caller is not approved, they must return false and not revert.
        r1 = c.logCreated(keepAddr);
        r2 = c.logRedemptionRequested(caller, digest, utxoSize, outputScript, requestedFee, outpoint);
        r3 = c.logGotRedemptionSignature(digest, r, s);
        r4 = c.logRegisteredPubkey(pubX, pubY);
        r5 = c.logSetupFailed();
        r6 = c.logFraudDuringSetup();
        r7 = c.logFunded();
        r8 = c.logCourtesyCalled();
        r9 = c.logStartedLiquidation(wasFraud);
        r10 = c.logRedeemed(txid);
        r11 = c.logLiquidated();
        r12 = c.logExitedCourtesyCall();

        // After all calls, the approval status must be unchanged and all return values must be false.
        assert(
            !before &&
            c.approvedToLog(caller) == before &&
            !r1 && !r2 && !r3 && !r4 && !r5 && !r6 &&
            !r7 && !r8 && !r9 && !r10 && !r11 && !r12
        );
    }
    receive() external payable {}
}

